//! 現在の tree-sitter が生成する parser.c (`Automatically @generated by tree-sitter`) の扱い (Issue #250)。

use super::support::*;

const PARSER_C: &str = "/* Automatically @generated by tree-sitter */\n\nvoid *demo_scanner_create(void);\nint demo_scanner_scan(void *payload);\n\nconst void *tree_sitter_demo(void) {\n  return demo_scanner_scan(demo_scanner_create()) ? 0 : 0;\n}\n";

const SCANNER_C: &str = "void *demo_scanner_create(void) {\n  return 0;\n}\n\nint demo_scanner_scan(void *payload) {\n  return payload != 0;\n}\n\nvoid unused_scanner_helper(void) {}\n";

/// 生成された parser と手書きの scanner・呼び出し元、`@generated` に触れる手書きのファイル。
fn grammar_repo() -> TestRepo {
    let repo = TestRepo::new();
    repo.create_dir_all("src");
    repo.write("src/parser.c", PARSER_C);
    repo.write("src/scanner.c", SCANNER_C);
    repo.write(
        "src/hand.c",
        "// Automatically @generated code is validated here.\nint demo_scanner_scan(void *payload);\n\nint hand_written_probe(void) {\n  return demo_scanner_scan(0);\n}\n",
    );
    repo
}

fn ref_paths(output: &serde_json::Value) -> Vec<String> {
    let mut paths: Vec<String> = output["refs"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| r["path"].as_str().unwrap().to_string())
        .collect();
    paths.dedup();
    paths
}

/// refs と symbols --dir は、旧形式のヘッダーと同じく parser.c を生成物として外して申告する。
/// `--include-generated` とファイル名を明示した `--glob` では含め、`**/*.c` では外したまま。
#[test]
fn refs_and_symbols_skip_current_tree_sitter_parser_and_report_it() {
    let repo = grammar_repo();
    for args in [
        vec!["--name", "demo_scanner_scan"],
        vec!["--names", "demo_scanner_scan"],
        vec!["--name", "demo_scanner_scan", "--glob", "**/*.c"],
    ] {
        let output = repo.run_json("refs", &args);
        assert_eq!(
            ref_paths(&output),
            ["src/scanner.c", "src/hand.c"],
            "{args:?}: {output}"
        );
        assert_eq!(output["skipped"]["generated"], 1, "{args:?}: {output}");
        assert_eq!(output["skipped"]["paths"][0], "src/parser.c");
    }
    for args in [
        vec!["--name", "demo_scanner_scan", "--include-generated"],
        vec!["--name", "demo_scanner_scan", "--glob", "**/parser.c"],
    ] {
        let output = repo.run_json("refs", &args);
        assert!(
            ref_paths(&output).iter().any(|path| path == "src/parser.c"),
            "{args:?}: {output}"
        );
        assert!(output.get("skipped").is_none(), "{args:?}: {output}");
    }

    let output = cargo_bin()
        .args(["symbols", "--dir"])
        .arg(repo.root())
        .output()
        .expect("run symbols --dir");
    assert!(output.status.success());
    let records: Vec<serde_json::Value> = String::from_utf8(output.stdout)
        .unwrap()
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect();
    let paths: Vec<_> = records.iter().filter_map(|r| r["path"].as_str()).collect();
    assert!(!paths.contains(&"src/parser.c"), "{records:?}");
    assert!(paths.contains(&"src/scanner.c") && paths.contains(&"src/hand.c"));
    assert!(
        records
            .iter()
            .any(|r| r["skipped"]["generated"] == 1 && r["skipped"]["paths"][0] == "src/parser.c"),
        "{records:?}"
    );
}

/// dead-code は parser.c を候補から外し、parser.c からの参照は数える。手書きの未使用は dead のまま。
/// `--include-generated` では parser.c の関数も候補になる。
#[test]
fn dead_code_counts_current_tree_sitter_parser_references_without_its_candidates() {
    let repo = grammar_repo();
    let dead_names = |output: &serde_json::Value| -> Vec<String> {
        let mut names: Vec<String> = output["dead_symbols"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| s["name"].as_str().unwrap().to_string())
            .collect();
        names.sort();
        names
    };
    let output = repo.run_json("dead-code", &[]);
    assert_eq!(
        dead_names(&output),
        ["hand_written_probe", "unused_scanner_helper"],
        "{output}"
    );
    assert_eq!(
        output["generated_candidates_skipped"]["paths"][0], "src/parser.c",
        "{output}"
    );
    let included = repo.run_json("dead-code", &["--include-generated"]);
    assert!(
        dead_names(&included)
            .iter()
            .any(|name| name == "tree_sitter_demo"),
        "{included}"
    );
}

fn caller_lines(value: &serde_json::Value, bucket: &str, path: &str) -> Vec<u64> {
    let mut lines: Vec<u64> = value["changes"]
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|change| change[bucket].as_array().cloned().unwrap_or_default())
        .filter(|caller| caller["path"] == path)
        .map(|caller| caller["line"].as_u64().unwrap())
        .collect();
    lines.sort_unstable();
    lines
}

fn run_impact(repo: &TestRepo) -> std::process::Output {
    cargo_bin()
        .arg("impact")
        .arg("--dir")
        .arg(repo.root())
        .arg("--git")
        .output()
        .expect("run impact --git")
}

/// 呼び出し元の検索は生成物も含める。生成された parser は手書きの scanner の関数の型に依存し、
/// C では翻訳単位が別なので型の不一致はコンパイルで見つからない。新旧どちらのヘッダーでも、
/// parser.c の宣言と呼び出しを呼び出し元に残し、impact は止める。
#[test]
fn impact_callers_include_generated_tree_sitter_parser_for_both_headers() {
    for header in [
        "/* Automatically @generated by tree-sitter */",
        "/* Automatically generated by tree-sitter. */",
    ] {
        let repo = grammar_repo();
        repo.write(
            "src/parser.c",
            PARSER_C.replacen("/* Automatically @generated by tree-sitter */", header, 1),
        );
        repo.init_git();
        repo.commit_all("base");
        repo.write(
            "src/scanner.c",
            SCANNER_C.replace(
                "int demo_scanner_scan(void *payload) {",
                "int demo_scanner_scan(void *payload, int flags) {",
            ),
        );
        let context = repo.run_json("context", &["--git"]);
        assert_eq!(
            caller_lines(&context, "impacted_callers", "src/parser.c"),
            [3, 6],
            "{header}: {context}"
        );
        assert_eq!(
            caller_lines(&context, "impacted_callers", "src/hand.c"),
            [1, 4],
            "{header}: {context}"
        );
        let review = repo.run_json("review", &["--git"]);
        assert_eq!(
            caller_lines(&review["impact"], "impacted_callers", "src/parser.c"),
            [3, 6],
            "{header}: {review}"
        );
        let impact = run_impact(&repo);
        assert_eq!(impact.status.code(), Some(1), "{header}");
        let stderr = String::from_utf8_lossy(&impact.stderr);
        assert!(stderr.contains("src/parser.c:4"), "{header}: {stderr}");
        assert!(stderr.contains("src/parser.c:7"), "{header}: {stderr}");
    }
}

/// 対照: 同じ差分で生成物の宣言も直した場合 (再生成) は解決済みで、本体だけの変更は呼び出し元を探さない。
#[test]
fn impact_generated_parser_callers_resolve_with_regeneration_and_ignore_body_changes() {
    let repo = grammar_repo();
    repo.init_git();
    repo.commit_all("base");
    let widened = "int demo_scanner_scan(void *payload, int flags)";
    repo.write(
        "src/scanner.c",
        SCANNER_C.replace(
            "int demo_scanner_scan(void *payload) {",
            &format!("{widened} {{"),
        ),
    );
    repo.write(
        "src/hand.c",
        "// Automatically @generated code is validated here.\nint demo_scanner_scan(void *payload, int flags);\n\nint hand_written_probe(void) {\n  return demo_scanner_scan(0, 0);\n}\n",
    );
    repo.write(
        "src/parser.c",
        PARSER_C
            .replace(
                "int demo_scanner_scan(void *payload);",
                &format!("{widened};"),
            )
            .replace(
                "demo_scanner_scan(demo_scanner_create())",
                "demo_scanner_scan(demo_scanner_create(), 0)",
            ),
    );
    let impact = run_impact(&repo);
    assert_eq!(
        impact.status.code(),
        Some(0),
        "{}",
        String::from_utf8_lossy(&impact.stderr)
    );

    let body_only = grammar_repo();
    body_only.init_git();
    body_only.commit_all("base");
    body_only.write(
        "src/scanner.c",
        SCANNER_C.replace("return payload != 0;", "return payload != (void *)0;"),
    );
    let context = body_only.run_json("context", &["--git"]);
    assert!(
        caller_lines(&context, "impacted_callers", "src/parser.c").is_empty(),
        "{context}"
    );
    assert_eq!(run_impact(&body_only).status.code(), Some(0));
}
